            return model
        model = _inner_model(training_indep, training_dep)
        best_configs = sorted(zip(training_indep, training_dep), key=lambda x: x[1])[:int(0.1 * len(training_indep))]
        estimators = model.estimators_
        every_column = file.independent_set
        header = file.features
        Rule, candidates = [], []
        if True:
            feature_names = file.features
            new_rows, new_perfs = [], []
            for row, perf in zip(training_indep, training_dep):
                if row not in new_rows:
                    new_rows.append(row)
                    new_perfs.append(perf)
            def _inner_get_tree_paths(tree, f_names):
                paths = []
                stack = [(0, [])]
                while stack:
                    node_id, path = stack.pop()
                    feature_index = tree.tree_.feature[node_id]
                    threshold = tree.tree_.threshold[node_id]

                    if feature_index != -2:
                        f_name = f_names[feature_index]
                        left_path = path + [(f_name, threshold, 'L')]
                        stack.append((tree.tree_.children_left[node_id], left_path))
                        right_path = path + [(f_name, threshold, 'R')]
                        stack.append((tree.tree_.children_right[node_id], right_path))
                    else:
                        paths.append(path)
                return paths
            rf_model = RandomForestRegressor(n_estimators=10, min_samples_leaf=int(10 + sample_plus))
            rf_model.fit(training_indep, training_dep)
