            def _inner_has_negative_value(lst):
                for item in lst:
                    if item < 0:
                        return True
                return False
            for i, path in zip(ACEs, valid_rules):
                if i < 0:
                    Rule += path
                    for indep, _ in best_configs:
                        if _inner_in_rule(indep, path, header):
                            break
        if (True and not _inner_has_negative_value(ACEs)) or not True:
            def cold_x_generator():
                return [random.choice(every_column[index]) for index in range(len(every_column))]
            def _inner_get_ei(pred, eta):
                def calculate_f():
                    z = (eta - m) / s
                    return (eta - m) * norm.cdf(z) + s * norm.pdf(z)
                pred_arr = np.array(pred).transpose(1, 0)
                m = np.mean(pred_arr, axis=1)
                s = np.std(pred_arr, axis=1)
                if np.any(s == 0.0):
                    s_copy = np.copy(s)
                    s[s_copy == 0.0] = 1.0
                    f = calculate_f()
                    f[s_copy == 0.0] = 0.0
                else:
                    f = calculate_f()
                return f
            best_value_cold = float('-inf')
            values_cold, xs_cold = [], []
            batch_size = 100
