                        results_rule[i] = random.sample(results_rule[i], 10)
                new_list = list(product(*results_rule))
                def dist_x_generator():
                    current_x = list(random.choice(new_list))
                    for idx in range(len(current_x)):
                        if current_x[idx] == '_':
                            current_x[idx] = random.choice(every_column[idx])
                    return current_x
                best_value_dist = float('-inf')
                values_dist, xs_dist = [], []
                batch_size = 100
                for batch_start in range(0, int(1e4), batch_size):
                    batch_end = min(batch_start + batch_size, int(1e4))
                    current_batch_size = batch_end - batch_start
                    batch_configs = [dist_x_generator() for _ in range(current_batch_size)]
                    batch_predictions = []
                    for estimator in estimators:
                        batch_pred = estimator.predict(batch_configs)
                        batch_predictions.append(batch_pred)
                    batch_predictions = np.array(batch_predictions).T
                    for i, current_x in enumerate(batch_configs):
                        pred = batch_predictions[i]
                        current_value = _inner_get_ei([pred], result)[0]
                        xs_dist.append(current_x)
                        values_dist.append(current_value)
                        if current_value > best_value_dist:
                            best_value_dist = current_value
                    if len(values_dist) > batch_size and len(values_dist) % (batch_size * 2) == 0:
                        try:
                            kde = stats.gaussian_kde(values_dist)
                            improvement_probability = 1 - kde.integrate_box_1d(-np.inf, best_value_dist)
                            if improvement_probability < 0.01:
                                break
                        except Exception:
                            break
                candidates.extend(xs_dist)
        if candidates:
            pred = [e.predict(candidates) for e in estimators]
            value = _inner_get_ei(pred, result)
            merged_predicted_objectives = [[i, a] for a, i in zip(value, candidates)]
            merged_predicted_objectives = sorted(merged_predicted_objectives, key=lambda x: x[1], reverse=True)
