import cma
import random
from util.Evaluate import evaluate
def run_tuners(file, budget=20, seed=0, maxlives=100):
    random.seed(seed)
    independent_set = file.independent_set
    best_result = float('inf')
    history_configs = {}
    consecutive_no_improve = 0
    used_budget = 0
    def map_to_enum_config(sol):
        new_config = []
        for i, values in enumerate(independent_set):
            index = int(abs(sol[i]) * len(values)) % len(values)
            new_config.append(values[index])
        return new_config
    initial_mean = [0.5] * len(independent_set)
    initial_sigma = 0.3
    es = cma.CMAEvolutionStrategy(
        initial_mean,
        initial_sigma,
        {'seed': seed, 'popsize': 4, 'maxiter': 1000000}
    )
    while used_budget < budget and consecutive_no_improve < maxlives:
        solutions = es.ask()
        current_valid_sols = []
        current_valid_scores = []
        for sol in solutions:
            generated_config = map_to_enum_config(sol)
            used_budget, consecutive_no_improve, history_configs, best_result, current_score, similar_config = evaluate(
                used_budget, consecutive_no_improve, history_configs, best_result, generated_config
            )
            current_valid_sols.append(sol)
            current_valid_scores.append(current_score)
            if used_budget >= budget or consecutive_no_improve >= maxlives:
                break
        if len(current_valid_sols) == 4:
            es.tell(current_valid_sols, current_valid_scores)
        else:
            break
        if used_budget >= budget or consecutive_no_improve >= maxlives:
            break
    return best_result

