from util.Evaluate import evaluate
def run_tuners(file, budget, seed, maxlives):
    current_seed = seed
    independent_set = file.independent_set
    D = len(independent_set)
    history_configs = {}
    crossover_rate = 0.5
    mutation_rate = 0.06
    pop_size = min(4*D,10)
    random.seed(current_seed)
    np.random.seed(current_seed)
    best_result = float('inf')
    best_config = None
    used_budget = 0
    consecutive_no_improve = 0
    population = []
    while len(population) < pop_size:
        config = [random.choice(values) for values in independent_set]
        ini_consecutive_no_improve = consecutive_no_improve
        ini_used_budget = used_budget
        used_budget, consecutive_no_improve, history_configs, best_result, current_score, similar_config = evaluate(
            used_budget, consecutive_no_improve, history_configs, best_result, config
        )
        if ini_consecutive_no_improve != consecutive_no_improve - 1 or ini_used_budget != used_budget:
            population.append((config, current_score))
            if current_score == best_result:
                best_config = similar_config
    while used_budget < budget and consecutive_no_improve < maxlives:
        confs_accepted = []
        for (parent_config, parent_score) in population:
            if used_budget >= budget or consecutive_no_improve >= maxlives:
                break
            child = parent_config.copy()
            crossover_indices = random.sample(range(D), int(D * crossover_rate))
            for idx in crossover_indices:
                child[idx] = best_config[idx]
            current_config = child
            mutated = current_config.copy()
            mutate_indices = random.sample(range(D), int(D * mutation_rate))
            for idx in mutate_indices:
                other_values = [v for v in independent_set[idx] if v != mutated[idx]]
                if other_values:
                    mutated[idx] = random.choice(other_values)
            current_config = mutated
            ini_consecutive_no_improve = consecutive_no_improve
            ini_used_budget = used_budget
            used_budget, consecutive_no_improve, history_configs, best_result, current_score, similar_config = evaluate(
                used_budget, consecutive_no_improve, history_configs, best_result, current_config
            )
            if ini_consecutive_no_improve == consecutive_no_improve - 1 and ini_used_budget == used_budget:
                continue
            if current_score == best_result:
                best_config = similar_config
            if used_budget >= budget or consecutive_no_improve >= maxlives:
                break
            current_perf = best_result
            new_perf = current_score
            if new_perf < current_perf or new_perf == 0:
                accept_prob = 1.0
            else:
                accept_prob = min(1.0, current_perf / new_perf)
            if random.random() < accept_prob:
                confs_accepted.append((current_config, current_score))
        if used_budget >= budget or consecutive_no_improve >= maxlives:
            break
        population = confs_accepted
        while len(population) < pop_size:
            if used_budget >= budget or consecutive_no_improve >= maxlives:
                break
            config = [random.choice(values) for values in independent_set]
            ini_consecutive_no_improve = consecutive_no_improve
            ini_used_budget = used_budget
            used_budget, consecutive_no_improve, history_configs, best_result, current_score, similar_config = evaluate(
                used_budget, consecutive_no_improve, history_configs, best_result, config
            )
            if ini_consecutive_no_improve != consecutive_no_improve - 1 or ini_used_budget != used_budget:
                population.append((config, current_score))
                if current_score == best_result:
                    best_config = similar_config
    return best_result

