                           'gender': random.choice(['C', 'N']),
                           'age': 0,
                           'score': None} for _ in range(population_size)]
            continue
        competitive.sort(key=lambda x: x['score'])
        num_mating = max(1, int(len(competitive) * 0.1))
        mating_c = competitive[:num_mating]
        non_competitive = [ind for ind in population if ind['gender'] == 'N']
        if not non_competitive:
            non_competitive = [{'config': [random.choice(values) for values in independent_set],
                                'gender': 'N',
                                'age': 0,
                                'score': None} for _ in range(population_size // 2)]
        offspring = []
        num_n_per_c = max(1, int(len(non_competitive) * (200 / 3) / 100))
        for c in mating_c:
            for n in random.sample(non_competitive, num_n_per_c):
                crossover_point = random.randint(1, len(c['config']) - 1)
                child_config = c['config'][:crossover_point] + n['config'][crossover_point:]
                mutation_rate = 0.1
                for i in range(len(child_config)):
                    if random.random() < mutation_rate:
                        values = independent_set[i]
                        other_values = [v for v in values if v != child_config[i]]
                        if other_values:
                            child_config[i] = random.choice(other_values)
                offspring.append({
                    'config': child_config,
                    'gender': random.choice(['C', 'N']),
                    'age': 0,
                    'score': None
                })
        for ind in population:
            ind['age'] += 1
        population = [ind for ind in population if ind['age'] <= 3]
        population.extend(offspring)
        if len(population) > population_size:
            population = random.sample(population, population_size)
        for ind in population:
            ind['score'] = None
    return best_result

import numpy as np
from util.Evaluate import evaluate
def run_tuners(file, budget, seed, maxlives):
    np.random.seed(seed)
    independent_set = file.independent_set
    hyperparameters = {f'param_{i}': values for i, values in enumerate(independent_set)}
    gamma = 0.1
    super_arms = list(hyperparameters.keys())
    k = len(super_arms)
    super_weights = {arm: 1.0 for arm in super_arms}
    sub_weights = {
        super_arm: {sub_arm: 1.0 for sub_arm in hyperparameters[super_arm]}
        for super_arm in super_arms
    }
    current_config = {super_arm: None for super_arm in super_arms}
    best_result = float('inf')
    history_configs = dict()
    consecutive_no_improve = 0
    used_budget = 0
    loop = 0
    while used_budget < budget and consecutive_no_improve < maxlives:
        loop += 1
        total_weight = sum(super_weights.values())
        probabilities = {
            arm: (1 - gamma) * (weight / total_weight) + gamma / k
            for arm, weight in super_weights.items()
        }
        arms = list(probabilities.keys())
        probs = list(probabilities.values())
        selected_super_arm = np.random.choice(arms, p=probs)
        super_arm = selected_super_arm
        sub_arms = hyperparameters[super_arm]
        sub_weight_dict = sub_weights[super_arm]
        total_sub_weight = sum(sub_weight_dict.values())
        if total_sub_weight == 0:
            selected_sub_arm = np.random.choice(sub_arms)
        else:
            if np.isinf(total_sub_weight):
                valid_weights = {k: v for k, v in sub_weight_dict.items() if not np.isinf(v)}
                if valid_weights:
                    selected_sub_arm = max(valid_weights, key=valid_weights.get)
                else:
                    selected_sub_arm = np.random.choice(sub_arms)
            else:
                sub_probabilities = {sub_arm: weight / total_sub_weight for sub_arm, weight in sub_weight_dict.items()}
                sub_arms_list = list(sub_probabilities.keys())
                sub_probs = list(sub_probabilities.values())
                selected_sub_arm = np.random.choice(sub_arms_list, p=sub_probs)
        current_config[selected_super_arm] = selected_sub_arm
        for arm in super_arms:
            if current_config[arm] is None:
                current_config[arm] = hyperparameters[arm][0]
        current_config_copy = current_config.copy()
        current_config_values = [current_config_copy[f'param_{i}'] for i in range(len(independent_set))]
        ini_consecutive_no_improve = consecutive_no_improve
        ini_used_budget = used_budget
        used_budget, consecutive_no_improve, history_configs, best_result, current_score, similar_config = evaluate(
            used_budget, consecutive_no_improve, history_configs, best_result, current_config_values
        )
        if ini_consecutive_no_improve == consecutive_no_improve - 1 and ini_used_budget == used_budget:
            continue
        score_min = min([v for v in history_configs.values()] + [current_score])
        score_max = max([v for v in history_configs.values()] + [current_score])
        if score_max == score_min:
            reward = 0.5
        else:
            reward = (score_max - current_score) / (score_max - score_min)
        total_super_weight = sum(super_weights.values())
        super_prob = (1 - gamma) * (super_weights[selected_super_arm] / total_super_weight) + gamma / k
        exp_super = min(gamma * reward / (k * super_prob), 709)
        super_weights[selected_super_arm] *= np.exp(exp_super)
        total_sub_weight_update = sum(sub_weights[selected_super_arm].values())
        sub_prob = sub_weights[selected_super_arm][selected_sub_arm] / total_sub_weight_update
        exp_sub = min(gamma * reward / sub_prob, 709)
        sub_weights[selected_super_arm][selected_sub_arm] *= np.exp(exp_sub)
    return best_result

import random
import numpy as np
from util.Evaluate import evaluate
def run_tuners(file, budget, seed,  maxlives):
    random.seed(seed)
    np.random.seed(seed)
    r = 10  
    s = 3   
    p_restart = 0.01  
    independent_set = file.independent_set
    hyperparameters = {f'param_{i}': values for i, values in enumerate(independent_set)}
    param_names = list(hyperparameters.keys())
    k = len(param_names)
    best_result = float('inf')
    history_configs = {}
    consecutive_no_improve = 0
    used_budget = 0
    initial_configs = [
        [random.choice(hyperparameters[param]) for param in param_names]
        for _ in range(r)
    ]
    current_config = None
    for config in initial_configs:
        ini_consecutive_no_improve = consecutive_no_improve
        ini_used_budget = used_budget
        used_budget, consecutive_no_improve, history_configs, best_result, score, similar_config = evaluate(
            used_budget, consecutive_no_improve, history_configs, best_result, config
        )
        if score == best_result:
            current_config = config
        if used_budget >= budget or consecutive_no_improve >= maxlives:
            break
        if ini_consecutive_no_improve == consecutive_no_improve - 1 and ini_used_budget == used_budget:
            continue
    while used_budget < budget and consecutive_no_improve < maxlives:
        inner_param_names = list(hyperparameters.keys())
        while used_budget < budget and consecutive_no_improve < maxlives:
            neighbors = []
            for i, param in enumerate(inner_param_names):
                current_value = current_config[i]
                for value in hyperparameters[param]:
                    if value != current_value:
                        neighbor = current_config.copy()
                        neighbor[i] = value
                        neighbors.append(neighbor)
            random.shuffle(neighbors)
            improved = False
            for neighbor in neighbors:
                ini_consecutive_no_improve = consecutive_no_improve
                ini_used_budget = used_budget
                used_budget, consecutive_no_improve, history_configs, best_result, score, similar_config = evaluate(
                    used_budget, consecutive_no_improve, history_configs, best_result, neighbor
                )
                if used_budget >= budget or consecutive_no_improve >= maxlives:
                    break
                if ini_consecutive_no_improve == consecutive_no_improve - 1 and ini_used_budget == used_budget:
                    continue
                if score == best_result:
                    improved = True
                    current_config = neighbor
                    break
            if not improved:
                break
        if used_budget >= budget or consecutive_no_improve >= maxlives:
            break
        perturbed_config = current_config.copy()
        for _ in range(s):
            param_idx = random.randint(0, k - 1)
            param = param_names[param_idx]
            current_value = perturbed_config[param_idx]
            possible_values = [v for v in hyperparameters[param] if v != current_value]
            if possible_values:
                perturbed_config[param_idx] = random.choice(possible_values)
        ini_consecutive_no_improve = consecutive_no_improve
        ini_used_budget = used_budget
        used_budget, consecutive_no_improve, history_configs, best_result, score, similar_config = evaluate(
            used_budget, consecutive_no_improve, history_configs, best_result, perturbed_config
        )
        if used_budget >= budget or consecutive_no_improve >= maxlives:
            break
        if ini_consecutive_no_improve == consecutive_no_improve - 1 and ini_used_budget == used_budget:
            continue
        if random.random() < p_restart:
            current_config = [random.choice(hyperparameters[param]) for param in param_names]
            ini_consecutive_no_improve = consecutive_no_improve
            ini_used_budget = used_budget
            used_budget, consecutive_no_improve, history_configs, best_result, current_score, similar_config = evaluate(
                used_budget, consecutive_no_improve, history_configs, best_result, current_config
            )
            if used_budget >= budget or consecutive_no_improve >= maxlives:
                break
            if ini_consecutive_no_improve == consecutive_no_improve - 1 and ini_used_budget == used_budget:
                continue
    return best_result
